$(function () {
    var $wrapper = $("#main-wrapper");
    var desktopMin = 992;

    function isDesktop() {
        return window.innerWidth >= desktopMin;
    }

    function closeMobileSidebar() {
        $wrapper.removeClass("show-sidebar");
        $("body").removeClass("sidebar-open");
    }

    function openMobileSidebar() {
        $wrapper.addClass("show-sidebar");
        $("body").addClass("sidebar-open");
    }

    function revealActiveNav() {
        var sidebar = document.querySelector(".left-sidebar .scroll-sidebar");
        var link = sidebar && sidebar.querySelector(".sidebar-link.active");
        if (!sidebar || !link) {
            return;
        }

        var sidebarRect = sidebar.getBoundingClientRect();
        var linkRect = link.getBoundingClientRect();
        var padding = 16;

        if (linkRect.top >= sidebarRect.top + padding && linkRect.bottom <= sidebarRect.bottom - padding) {
            return;
        }

        var nextTop = sidebar.scrollTop + (linkRect.top - sidebarRect.top) - padding;
        sidebar.scrollTop = Math.max(0, nextTop);
    }

    function syncSidebarMode() {
        if (!$wrapper.length) {
            return;
        }

        $wrapper.attr("data-sidebartype", "full");
        $wrapper.removeClass("mini-sidebar");

        if (isDesktop()) {
            closeMobileSidebar();
        }
    }

    if ("scrollRestoration" in history) {
        history.scrollRestoration = "manual";
    }
    window.scrollTo(0, 0);

    syncSidebarMode();
    $(window).on("resize", syncSidebarMode);
    revealActiveNav();

    $(document).on("click", ".sidebartoggler", function (event) {
        event.preventDefault();
        if (isDesktop()) {
            return;
        }
        if ($wrapper.hasClass("show-sidebar")) {
            closeMobileSidebar();
        } else {
            openMobileSidebar();
        }
    });

    $(document).on("click", ".sidebar-backdrop", function () {
        closeMobileSidebar();
    });

    $(document).on("keydown", function (event) {
        if (event.key === "Escape") {
            closeMobileSidebar();
        }
    });
});
